pm.test("Status code is 200", () => pm.response.to.have.status(200));

const body = pm.response.json();
const order = pm.request.url.query.get("sort");   // "asc" or "desc"

pm.test("Products are sorted by id (" + order + ")", () => {
    const ids = body.map(p => p.id);
    const sorted = [...ids].sort((a, b) => order === "desc" ? b - a : a - b);
    pm.expect(ids).to.eql(sorted);
});

